// LRU cache dung lượng cố định, hoạt động từ Java 8 trở đi
class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    LruCache(int capacity) {
        super(16, 0.75f, true);   // tham số thứ ba: accessOrder = true
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;  // CHỈ trả boolean, không tự gọi remove()
    }
}

