// 1. split nhận REGEX
"1.2.3".split(".").length;        // 0  (!) - "." khớp mọi ký tự
"1.2.3".split("\\.").length;      // 3
"a|b".split("|");                 // [a, |, b]  (!) - "|" là toán tử OR rỗng
"a|b".split(Pattern.quote("|"));  // [a, b]

// 2. Chuỗi rỗng ở cuối bị cắt, ở đầu thì giữ
"a,b,,c,,".split(",");            // [a, b, , c]      length = 4
"a,b,,c,,".split(",", -1);        // [a, b, , c, , ]  length = 6
",a,b".split(",");                // [, a, b]         length = 3

// 3. limit dương: giữ nguyên phần đuôi
"a,b,,c,,".split(",", 3);         // [a, b, ,c,,]
"key=a=b=c".split("=", 2);        // [key, a=b=c]  <- dùng cho cặp key/value

