// 4. Biên dịch một lần, dùng nhiều lần
public final class LogParser {
    private static final Pattern LEVEL = Pattern.compile("^\\[(\\w+)\\]");

    static String level(String line) {
        Matcher m = LEVEL.matcher(line);   // Matcher tạo cục bộ, KHÔNG static
        return m.find() ? m.group(1) : null;
    }
}

